const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

test("bulk-add: rejects the whole batch when the cumulative count exceeds the owner's cap", async () => {
  const { base, close } = startServer();
  try {
    const resp = await api(base, "POST", "/api/links/bulk-add", {
      owner: "dev",
      links: [
        { url: "https://a.example.com" },
        { url: "https://b.example.com" },
        { url: "https://c.example.com" },
        { url: "https://d.example.com" },
      ],
    });
    assert.strictEqual(resp.status, 400);

    const listed = await api(base, "GET", "/api/links");
    assert.strictEqual(listed.json.length, 0);
  } finally {
    await close();
  }
});

test("bulk-add: succeeds within capacity", async () => {
  const { base, close } = startServer();
  try {
    const resp = await api(base, "POST", "/api/links/bulk-add", {
      owner: "dev",
      links: [{ url: "https://a.example.com" }, { url: "https://b.example.com" }],
    });
    assert.strictEqual(resp.status, 201);
  } finally {
    await close();
  }
});

