import express from "express";

import { MAX_URL_LENGTH } from "../config";
import { Link } from "../models/types";
import { isValidSlug, randomSlug } from "../services/slugService";
import * as store from "../store/linkStore";

export const linksRouter = express.Router();

const MAX_LINKS_PER_OWNER = 3;

linksRouter.post("/", (req, res) => {
  const body = req.body ?? {};
  const url = typeof body.url === "string" ? body.url : "";
  if (url.length === 0 || url.length > MAX_URL_LENGTH) {
    res.status(400).json({ error: "url is required" });
    return;
  }

  let slug: string;
  if (body.slug !== undefined) {
    if (typeof body.slug !== "string" || !isValidSlug(body.slug)) {
      res.status(400).json({ error: "invalid slug" });
      return;
    }
    slug = body.slug;
  } else {
    do {
      slug = randomSlug();
    } while (store.getLink(slug) !== undefined);
  }

  if (store.getLink(slug) !== undefined) {
    res.status(409).json({ error: "slug already taken" });
    return;
  }

  const link: Link = { slug, url, createdAt: new Date().toISOString() };
  store.createLink(link);
  res.status(201).json(link);
});

linksRouter.post("/bulk-add", (req, res) => {
  const body = req.body ?? {};
  const owner = typeof body.owner === "string" ? body.owner : "";
  if (owner.length === 0) {
    res.status(400).json({ error: "owner is required" });
    return;
  }
  if (!Array.isArray(body.links) || body.links.length === 0) {
    res.status(400).json({ error: "links must be a non-empty array" });
    return;
  }

  const seenSlugs = new Set<string>();
  const validated: { slug: string; url: string }[] = [];
  for (const raw of body.links) {
    const url = typeof raw?.url === "string" ? raw.url : "";
    if (url.length === 0 || url.length > MAX_URL_LENGTH) {
      res.status(400).json({ error: "url is required" });
      return;
    }
    let slug: string;
    if (raw?.slug !== undefined) {
      if (typeof raw.slug !== "string" || !isValidSlug(raw.slug)) {
        res.status(400).json({ error: "invalid slug" });
        return;
      }
      slug = raw.slug;
    } else {
      do {
        slug = randomSlug();
      } while (store.getLink(slug) !== undefined || seenSlugs.has(slug));
    }
    if (store.getLink(slug) !== undefined || seenSlugs.has(slug)) {
      res.status(409).json({ error: `slug already taken: ${slug}` });
      return;
    }
    seenSlugs.add(slug);
    validated.push({ slug, url });
  }

  const current = store.countByOwner(owner);
  if (current + validated.length > MAX_LINKS_PER_OWNER) {
    res.status(400).json({ error: "batch would exceed owner's maximum number of links" });
    return;
  }

  const created = validated.map(({ slug, url }) => {
    const link: Link = { slug, url, createdAt: new Date().toISOString(), owner };
    store.createLink(link);
    return link;
  });
  res.status(201).json(created);
});

linksRouter.get("/", (_req, res) => {
  res.status(200).json(store.listLinks());
});

linksRouter.get("/:slug", (req, res) => {
  const link = store.getLink(req.params.slug);
  if (link === undefined) {
    res.status(404).json({ error: "link not found" });
    return;
  }
  res.status(200).json(link);
});

linksRouter.delete("/:slug", (req, res) => {
  if (!store.deleteLink(req.params.slug)) {
    res.status(404).json({ error: "link not found" });
    return;
  }
  res.status(204).send();
});

